import{_ as e,c as a,o as r,a4 as l}from"./chunks/framework.ssOvXUgL.js";const m=JSON.parse('{"title":"基本配置","description":"","frontmatter":{"sidebar":"auto"},"headers":[],"relativePath":"config/base.md","filePath":"config/base.md","lastUpdated":1728809929000}'),o={name:"config/base.md"},t=l('<h1 id="基本配置" tabindex="-1">基本配置 <a class="header-anchor" href="#基本配置" aria-label="Permalink to &quot;基本配置&quot;">​</a></h1><p>项目首次运行时，会在 <code>config</code> 目录下生成一系列配置文件，本文将对除 <code>commands.yml</code> 外的配置项做出相关解释。 <code>commands.yml</code> 的相关配置说明请参考 <a href="/config/commands.html">指令配置</a>。</p><h2 id="base-yml" tabindex="-1">base.yml <a class="header-anchor" href="#base-yml" aria-label="Permalink to &quot;base.yml&quot;">​</a></h2><p>bot 运行相关的基本配置。</p><h3 id="reverseclient" tabindex="-1">reverseClient <a class="header-anchor" href="#reverseclient" aria-label="Permalink to &quot;reverseClient&quot;">​</a></h3><ul><li>类型: <a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Boolean" target="_blank" rel="noreferrer">boolean</a></li><li>缺省值: <code>false</code></li></ul><p>定义 bot 与实现端的连接方式，默认为 <code>false</code> 即<strong>正向 ws 连接</strong>，由 bot 主动去连接实现端，需填写下方的 <code>wsServer</code> 与 <code>wsApiServer</code> 配置。<br> 反之设为 <code>true</code> 时为<strong>反向 ws 连接</strong>，由 bot 创建 ws 服务，被动等待实现端连接，需填写下方的 <code>wsPort</code> 配置。</p><h3 id="wsserver" tabindex="-1">wsServer <a class="header-anchor" href="#wsserver" aria-label="Permalink to &quot;wsServer&quot;">​</a></h3><ul><li>类型: <a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/String" target="_blank" rel="noreferrer">string</a></li><li>缺省值: <code>127.0.0.1:11451</code></li></ul><p>仅当 <code>reverseClient</code> 为 <code>false</code> 时有效。</p><p>OneBot 实现所提供 event 事件上报的正向 websocket 地址.</p><h3 id="wsapiserver" tabindex="-1">wsApiServer <a class="header-anchor" href="#wsapiserver" aria-label="Permalink to &quot;wsApiServer&quot;">​</a></h3><ul><li>类型: <a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/String" target="_blank" rel="noreferrer">string</a></li></ul><p>仅当 <code>reverseClient</code> 为 <code>false</code> 时有效。</p><p>OneBot 实现所提供 api 调用的正向 websocket 地址，当置空时，默认使用 <a href="#wsServer">wsServer</a>。</p><h3 id="wsport" tabindex="-1">wsPort <a class="header-anchor" href="#wsport" aria-label="Permalink to &quot;wsPort&quot;">​</a></h3><ul><li>类型: <a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/String" target="_blank" rel="noreferrer">string</a></li><li>缺省值: <code>11451</code></li></ul><p>仅当 <code>reverseClient</code> 为 <code>true</code> 时有效。</p><p>提供给 OneBot 实现连接的 websocket 服务所占用的端口，完整链接为 <code>ws://127.0.0.1:{wsPort}</code>，填入 OneBot 实现的<strong>反向ws连接地址列表</strong>即可。</p><blockquote><p>需要注意的是，若使用 Docker 方式部署，则需要在 <code>docker-compose.yml</code> 的 <code>bot.port</code> 中放行对应端口。</p></blockquote><h3 id="master" tabindex="-1">master <a class="header-anchor" href="#master" aria-label="Permalink to &quot;master&quot;">​</a></h3><ul><li>类型: <a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Number" target="_blank" rel="noreferrer">number</a></li><li>缺省值: <code>987654321</code></li></ul><p>BOT 持有者（或称主人）的 QQ 账号，唯一指定，拥有 BOT 最高权限。</p><h3 id="inviteauth" tabindex="-1">inviteAuth <a class="header-anchor" href="#inviteauth" aria-label="Permalink to &quot;inviteAuth&quot;">​</a></h3><ul><li>类型: <code>1|2|3</code></li><li>缺省值: <code>2</code></li></ul><p>邀请 BOT 入群时，BOT 自动接受入群邀请的权限等级，每个权限等级的对应如下：</p><ul><li>1: 仅自动接收 <strong>BOT 持有者</strong>的入群邀请。</li><li>2: 自动接受 <strong>BOT 管理员</strong> 与 <strong>BOT 持有者</strong>的入群邀请。</li><li>3: 自动接受<strong>被封禁用户外</strong>的所有人的入群邀请。</li></ul><h3 id="loglevel" tabindex="-1">logLevel <a class="header-anchor" href="#loglevel" aria-label="Permalink to &quot;logLevel&quot;">​</a></h3><ul><li>类型: <code>all|trace|debug|info|warn|error|fatal|mark|off</code></li><li>缺省值: <code>info</code></li></ul><p>日志输出等级，等级从前往后依次递减。日志输出会过滤掉比所设置等级更高的等级日志，<code>all</code> 输出全部日志，<code>off</code> 不输出任何日志。</p><h3 id="atuser" tabindex="-1">atUser <a class="header-anchor" href="#atuser" aria-label="Permalink to &quot;atUser&quot;">​</a></h3><ul><li>类型: <a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Boolean" target="_blank" rel="noreferrer">boolean</a></li><li>缺省值: <code>false</code></li></ul><p>BOT 在响应指令时，是否需要 at 用户。部分指令的响应无视本项配置。</p><h3 id="atbot" tabindex="-1">atBOT <a class="header-anchor" href="#atbot" aria-label="Permalink to &quot;atBOT&quot;">​</a></h3><ul><li>类型: <a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Boolean" target="_blank" rel="noreferrer">boolean</a></li><li>缺省值: <code>false</code></li></ul><p>是否需要在使用指令时 @BOT 账号，只在群聊中生效。@BOT 必须在最前面，例如 <code>@Adachi-BOT #help</code>。</p><h3 id="addfriend" tabindex="-1">addFriend <a class="header-anchor" href="#addfriend" aria-label="Permalink to &quot;addFriend&quot;">​</a></h3><ul><li>类型: <a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Boolean" target="_blank" rel="noreferrer">boolean</a></li><li>缺省值: <code>true</code></li></ul><p>是否强制要求添加好友后才能使用 BOT，开启后未添加好友时 BOT 将不会响应并提示对方请先添加好友。</p><h3 id="apitimeout" tabindex="-1">apiTimeout <a class="header-anchor" href="#apitimeout" aria-label="Permalink to &quot;apiTimeout&quot;">​</a></h3><ul><li>类型: <a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Number" target="_blank" rel="noreferrer">number</a></li><li>缺省值: <code>20000</code></li></ul><p>设置等待 OneBot 实现响应 api 的最大等待时间，超出后报错 <code>${ action } 响应超时</code>，单位秒。</p><h3 id="renderport" tabindex="-1">renderPort <a class="header-anchor" href="#renderport" aria-label="Permalink to &quot;renderPort&quot;">​</a></h3><ul><li>类型: <a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Number" target="_blank" rel="noreferrer">number</a></li><li>缺省值: <code>80</code></li></ul><p>BOT 启动所依赖端口（网页控制台、公共路由等）。</p><p>若使用 <code>docker</code> 启动，则修改此项后应同步更改 <code>docker-compose.yml</code> 中 <code>port</code> 的第二个值。</p><h2 id="directive-yml" tabindex="-1">directive.yml <a class="header-anchor" href="#directive-yml" aria-label="Permalink to &quot;directive.yml&quot;">​</a></h2><p>指令发送的相关配置。</p><h3 id="header" tabindex="-1">header <a class="header-anchor" href="#header" aria-label="Permalink to &quot;header&quot;">​</a></h3><ul><li>类型: <code>string[]</code></li><li>缺省值: <code>[ &quot;#&quot; ]</code></li></ul><p>指令起始符。用于标识 BOT 指令的特殊符号，可配置多项，</p><p>例如：当 <code>header</code> 数组包含 <code>#</code> 时，需使用 <code>#help</code> 来触发帮助指令，<code>help</code> 会被忽略。如果不想在指令前添加特殊符号，请设置为空数组 <code>[]</code> 。</p><h3 id="groupintervaltime" tabindex="-1">groupIntervalTime <a class="header-anchor" href="#groupintervaltime" aria-label="Permalink to &quot;groupIntervalTime&quot;">​</a></h3><ul><li>类型: <a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Number" target="_blank" rel="noreferrer">number</a></li><li>缺省值: <code>1500</code></li></ul><p>群聊中指令操作冷却时间，单位为毫秒(ms)，不支持小数。</p><h3 id="privateintervaltime" tabindex="-1">privateIntervalTime <a class="header-anchor" href="#privateintervaltime" aria-label="Permalink to &quot;privateIntervalTime&quot;">​</a></h3><ul><li>类型: <a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Number" target="_blank" rel="noreferrer">number</a></li><li>缺省值: <code>2000</code></li></ul><p>私聊中指令操作冷却时间，单位为毫秒(ms)，不支持小数。</p><h3 id="helpmessagestyle" tabindex="-1">helpMessageStyle <a class="header-anchor" href="#helpmessagestyle" aria-label="Permalink to &quot;helpMessageStyle&quot;">​</a></h3><ul><li>类型: <code>message|forward|xml|card</code></li><li>缺省值: <code>message</code></li></ul><p>帮助信息样式，每个配置的对应解释如下：</p><ul><li><code>message</code> 样式为所有指令以单条消息直接发送。</li><li><code>forward</code> 样式为每条指令为单条消息，并整合为合并转发的形式发送。</li><li><code>xml</code> 样式为所有指令以 xml 卡片的形式进行发送，此方式有一定封号风险，不建议大群使用。</li><li><code>card</code> 以图片形式发送，此种方式发送速度略慢于上面三种，但比较直观。</li></ul><h3 id="fuzzymatch" tabindex="-1">fuzzyMatch <a class="header-anchor" href="#fuzzymatch" aria-label="Permalink to &quot;fuzzyMatch&quot;">​</a></h3><ul><li>类型: <a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Boolean" target="_blank" rel="noreferrer">boolean</a></li><li>缺省值: <code>false</code></li></ul><p>启用中文模糊匹配。开启后 BOT 会对中文指令进行模糊匹配，要求必须以 <code>header</code> 开头且中文指令不得拆开。</p><p>例如在 <code>header</code> 配置为 <code>[ &quot;#&quot; ]</code> 时，对于<code>攻略（角色名）</code>指令，有如下情况：</p><ul><li><code>#攻略行秋</code>、<code>#攻略 行秋</code>: 正常触发</li><li><code>#行秋攻略</code>、<code>#行攻略秋</code>: 被解析为 <code>#攻略 行秋</code> 并正常触发</li><li><code>#行攻秋略</code>: 无法触发，指令头不能被拆分</li><li><code>行秋#攻略</code>: 无法触发，必须以 <code>#</code> 起始</li></ul><p>需要注意的是，此项与无指令头中文指令（例如 <code>__攻略</code> 或 <code>header</code> 置空）会发证某些奇妙的化学反应，导致误触率极高.</p><p>还是以<code>攻略（角色名）</code>指令为例，在 <code>header</code> 配置为 <code>[]</code> 时，，有如下情况：</p><ul><li><code>这个攻略不太靠谱</code>: 被解析为 <code>攻略 这个不太靠谱</code>，并触发指令，导致 BOT 响应：<code>未找到角色 这个不太靠谱</code>。</li></ul><p>因此如果你有使用无指令头中文指令的需求，请慎重开启此项。</p><h3 id="matchprompt" tabindex="-1">matchPrompt <a class="header-anchor" href="#matchprompt" aria-label="Permalink to &quot;matchPrompt&quot;">​</a></h3><ul><li>类型: <a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Boolean" target="_blank" rel="noreferrer">boolean</a></li><li>缺省值: <code>true</code></li></ul><p>启用参数校验提示。开启后若指令参数错误，BOT 将会给予提示。</p><h3 id="concurrency" tabindex="-1">concurrency <a class="header-anchor" href="#concurrency" aria-label="Permalink to &quot;concurrency&quot;">​</a></h3><ul><li>类型: <a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Number" target="_blank" rel="noreferrer">number</a></li><li>缺省值: <code>10</code></li></ul><p>bot 可并发响应的指令数量，同时响应的指令数量超过这个数值后，将会排队等待响应。</p><h3 id="calltimes" tabindex="-1">callTimes <a class="header-anchor" href="#calltimes" aria-label="Permalink to &quot;callTimes&quot;">​</a></h3><ul><li>类型: <a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Number" target="_blank" rel="noreferrer">number</a></li><li>缺省值: <code>3</code></li></ul><p>指令 <strong>联系bot持有者</strong> 每个人一天内可使用的最大次数。</p><h3 id="countthreshold" tabindex="-1">countThreshold <a class="header-anchor" href="#countthreshold" aria-label="Permalink to &quot;countThreshold&quot;">​</a></h3><ul><li>类型: <a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Number" target="_blank" rel="noreferrer">number</a></li><li>缺省值: <code>60</code></li></ul><p>用户在一小时使用指令的次数的阈值，按整点计算，如 <code>13:00~14:00</code> 。如果用户在过去一小时内使用指令的次数超过了该值，BOT 会向持有者发送私聊信息，提示所有超量使用的用户和使用次数，以便持有者对超量使用指令的用户进行处理。</p><h3 id="thresholdinterval" tabindex="-1">ThresholdInterval <a class="header-anchor" href="#thresholdinterval" aria-label="Permalink to &quot;ThresholdInterval&quot;">​</a></h3><ul><li>类型: <a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Boolean" target="_blank" rel="noreferrer">boolean</a></li><li>缺省值: <code>false</code></li></ul><p>开启后当用户使用超过 <code>countThreshold</code> 所设置的阈值时，本小时内 BOT 将不再响应其指令。</p><h2 id="db-yml" tabindex="-1">db.yml <a class="header-anchor" href="#db-yml" aria-label="Permalink to &quot;db.yml&quot;">​</a></h2><p><code>redis</code> 数据库相关配置。</p><h3 id="port" tabindex="-1">port <a class="header-anchor" href="#port" aria-label="Permalink to &quot;port&quot;">​</a></h3><ul><li>类型: <a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Number" target="_blank" rel="noreferrer">number</a></li><li>缺省值: <code>6379</code></li></ul><p>数据库端口。</p><blockquote><p>注意，Docker 启动时修改此值，需同时将 <code>redis.conf</code> 中的 <code>port</code> 修改为与此处相同的值。</p></blockquote><h3 id="password" tabindex="-1">password <a class="header-anchor" href="#password" aria-label="Permalink to &quot;password&quot;">​</a></h3><ul><li>类型: <a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/String" target="_blank" rel="noreferrer">string</a></li><li>缺省值: <code>&quot;&quot;</code></li></ul><p>数据库密码。非必填项，依照个人需求设置。</p><h2 id="mail-yml" tabindex="-1">mail.yml <a class="header-anchor" href="#mail-yml" aria-label="Permalink to &quot;mail.yml&quot;">​</a></h2><p>用于主动发送邮件的相关功能，使用 <code>SMTP</code> 协议发送邮件。</p><h3 id="host" tabindex="-1">host <a class="header-anchor" href="#host" aria-label="Permalink to &quot;host&quot;">​</a></h3><ul><li>类型: <a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/String" target="_blank" rel="noreferrer">string</a></li><li>缺省值: <code>&quot;smtp.qq.com&quot;</code></li></ul><p>邮箱服务的主机名或 IP 地址，例如qq服务为smtp.qq.com。</p><h3 id="port-1" tabindex="-1">port <a class="header-anchor" href="#port-1" aria-label="Permalink to &quot;port&quot;">​</a></h3><ul><li>类型: <a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Number" target="_blank" rel="noreferrer">number</a></li><li>缺省值: <code>587</code></li></ul><p>邮箱服务的端口，配置项 <code>secure</code> 关闭时默认 <code>587</code>，反之 <code>465</code>。</p><h3 id="user" tabindex="-1">user <a class="header-anchor" href="#user" aria-label="Permalink to &quot;user&quot;">​</a></h3><ul><li>类型: <a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/String" target="_blank" rel="noreferrer">string</a></li><li>缺省值: <code>&quot;123456789@qq.com&quot;</code></li></ul><p>邮箱账号。</p><h3 id="pass" tabindex="-1">pass <a class="header-anchor" href="#pass" aria-label="Permalink to &quot;pass&quot;">​</a></h3><ul><li>类型: <a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/String" target="_blank" rel="noreferrer">string</a></li><li>缺省值: <code>&quot;&quot;</code></li></ul><p>邮箱密码，各平台互不相同，如qq邮箱为授权码，请参考各自平台进行配置</p><h3 id="secure" tabindex="-1">secure <a class="header-anchor" href="#secure" aria-label="Permalink to &quot;secure&quot;">​</a></h3><ul><li>类型: <a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Boolean" target="_blank" rel="noreferrer">boolean</a></li><li>缺省值: <code>false</code></li></ul><p>是否开启安全连接，参考 <code>port</code> 解释。</p><h3 id="servername" tabindex="-1">servername <a class="header-anchor" href="#servername" aria-label="Permalink to &quot;servername&quot;">​</a></h3><ul><li>类型: <a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/String" target="_blank" rel="noreferrer">string</a></li><li>缺省值: <code>&quot;&quot;</code></li></ul><p>验证主机名，<code>host</code> 设置为<strong>IP地址</strong>时可选的 TLS 验证主机名。仅 <code>secure</code> 开启时有效。</p><h3 id="rejectunauthorized" tabindex="-1">rejectUnauthorized <a class="header-anchor" href="#rejectunauthorized" aria-label="Permalink to &quot;rejectUnauthorized&quot;">​</a></h3><ul><li>类型: <a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Boolean" target="_blank" rel="noreferrer">boolean</a></li><li>缺省值: <code>false</code></li></ul><p>证书校验。仅 <code>secure</code> 开启时有效。</p><p>建议关闭，开启可能会存在认证问题。</p><h3 id="logoutsend" tabindex="-1">logoutSend <a class="header-anchor" href="#logoutsend" aria-label="Permalink to &quot;logoutSend&quot;">​</a></h3><ul><li>类型: <a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Boolean" target="_blank" rel="noreferrer">boolean</a></li><li>缺省值: <code>false</code></li></ul><p>是否开启离线发送邮件功能。开启后当 BOT 意外掉线时，自动向 Master 的 QQ 邮箱发送邮件提醒。</p><h3 id="senddelay" tabindex="-1">sendDelay <a class="header-anchor" href="#senddelay" aria-label="Permalink to &quot;sendDelay&quot;">​</a></h3><ul><li>类型: <a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Number" target="_blank" rel="noreferrer">number</a></li><li>缺省值: <code>5</code></li></ul><p>BOT 离线多久后发送提醒邮件，期间 BOT 恢复上线则不会继续发送邮件，单位 <strong>分钟</strong>。仅 <code>logoutSend</code> 开启时有效。</p><h3 id="retry" tabindex="-1">retry <a class="header-anchor" href="#retry" aria-label="Permalink to &quot;retry&quot;">​</a></h3><ul><li>类型: <a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Number" target="_blank" rel="noreferrer">number</a></li><li>缺省值: <code>3</code></li></ul><p>离线邮件发送失败时重新尝试发送的次数。仅 <code>logoutSend</code> 开启时有效。</p><h3 id="retrywait" tabindex="-1">retryWait <a class="header-anchor" href="#retrywait" aria-label="Permalink to &quot;retryWait&quot;">​</a></h3><ul><li>类型: <a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Number" target="_blank" rel="noreferrer">number</a></li><li>缺省值: <code>5</code></li></ul><p>离线邮件发送失败后延迟多久重新尝试发送，单位 <strong>分钟</strong>。仅 <code>logoutSend</code> 开启时有效。</p><h2 id="webconsole-yml" tabindex="-1">webConsole.yml <a class="header-anchor" href="#webconsole-yml" aria-label="Permalink to &quot;webConsole.yml&quot;">​</a></h2><p>网页控制台相关配置。</p><h3 id="enable" tabindex="-1">enable <a class="header-anchor" href="#enable" aria-label="Permalink to &quot;enable&quot;">​</a></h3><ul><li>类型: <a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Boolean" target="_blank" rel="noreferrer">boolean</a></li><li>缺省值: <code>true</code></li></ul><p>是否启用 <code>Web Console</code> 即网页控制台功能，开启后将停止终端的日志打印行为。</p><h3 id="tcploggerport" tabindex="-1">tcpLoggerPort <a class="header-anchor" href="#tcploggerport" aria-label="Permalink to &quot;tcpLoggerPort&quot;">​</a></h3><ul><li>类型: <a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Number" target="_blank" rel="noreferrer">number</a></li><li>缺省值: <code>54921</code></li></ul><p><code>log4js</code> 日志输出端口，除非端口冲突否则不需要改动。</p><h4 id="loghighwatermark" tabindex="-1">logHighWaterMark <a class="header-anchor" href="#loghighwatermark" aria-label="Permalink to &quot;logHighWaterMark&quot;">​</a></h4><ul><li>类型: <a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Number" target="_blank" rel="noreferrer">number</a></li><li>缺省值: <code>64</code></li></ul><p>控制日志单次读取的数据量，单位 <code>kb</code>，不填或置 0 时默认 <code>64</code>，越大读取越快，内存占用越高，反之同理。</p><h4 id="jwtsecret" tabindex="-1">jwtSecret <a class="header-anchor" href="#jwtsecret" aria-label="Permalink to &quot;jwtSecret&quot;">​</a></h4><ul><li>类型: <a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/String" target="_blank" rel="noreferrer">string</a></li><li>缺省值: <code>&quot;&quot;</code></li></ul><p>JWT 验证秘钥，默认随机生成，可以随意输入长度为 6~16 的仅由字母和数字组成的字符串，最好不要有特殊含义。</p><p>该密钥还用于初次打开网页控制台时创建初始账号，请注意不要泄露该密钥。</p><h2 id="autochat-yml" tabindex="-1">autoChat.yml <a class="header-anchor" href="#autochat-yml" aria-label="Permalink to &quot;autoChat.yml&quot;">​</a></h2><p>自动聊天配置，可以通过群聊中 <code>@BOT</code> 或私聊发送非指令语句来触发自动对话（当开启 <code>atBOT</code> 时，群聊中 <code>@BOT</code> 无效）。</p><h3 id="enable-1" tabindex="-1">enable <a class="header-anchor" href="#enable-1" aria-label="Permalink to &quot;enable&quot;">​</a></h3><ul><li>类型: <a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Boolean" target="_blank" rel="noreferrer">boolean</a></li><li>缺省值: <code>false</code></li></ul><p>是否启用自动聊天功能。</p><h3 id="type" tabindex="-1">type <a class="header-anchor" href="#type" aria-label="Permalink to &quot;type&quot;">​</a></h3><ul><li>类型: <code>1|2|3</code></li><li>缺省值: <code>1</code></li></ul><p>聊天 api 所使用的平台，不同值指代的平台如下：</p><ul><li>1: 青云客</li><li>2: 腾讯NLP（腾讯自然语言处理）</li><li>3: 小爱同学</li></ul><h3 id="audio" tabindex="-1">audio <a class="header-anchor" href="#audio" aria-label="Permalink to &quot;audio&quot;">​</a></h3><ul><li>类型: <a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Boolean" target="_blank" rel="noreferrer">boolean</a></li><li>缺省值: <code>false</code></li></ul><p>是否开启语音发送功能，仅 <code>type</code> 为 <code>3</code> 时可用。</p><h3 id="secretid" tabindex="-1">secretId <a class="header-anchor" href="#secretid" aria-label="Permalink to &quot;secretId&quot;">​</a></h3><ul><li>类型: <a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/String" target="_blank" rel="noreferrer">string</a></li><li>缺省值: <code>&quot;&quot;</code></li></ul><p>前往腾讯云开通 NLP 后获取，仅 <code>type</code> 为 <code>2</code> 时可用。</p><h3 id="secretkey" tabindex="-1">secretKey <a class="header-anchor" href="#secretkey" aria-label="Permalink to &quot;secretKey&quot;">​</a></h3><ul><li>类型: <a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/String" target="_blank" rel="noreferrer">string</a></li><li>缺省值: <code>&quot;&quot;</code></li></ul><p>前往腾讯云开通 NLP 后获取，仅 <code>type</code> 为 <code>2</code> 时可用。</p><h2 id="whitelist-yml" tabindex="-1">whiteList.yml <a class="header-anchor" href="#whitelist-yml" aria-label="Permalink to &quot;whiteList.yml&quot;">​</a></h2><p>白名单配置，使 BOT 仅对白名单内的用户或群组作出响应。</p><h3 id="enable-2" tabindex="-1">enable <a class="header-anchor" href="#enable-2" aria-label="Permalink to &quot;enable&quot;">​</a></h3><ul><li>类型: <a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Boolean" target="_blank" rel="noreferrer">boolean</a></li><li>缺省值: <code>false</code></li></ul><p>是否启用白名单模式。</p><h3 id="user-1" tabindex="-1">user <a class="header-anchor" href="#user-1" aria-label="Permalink to &quot;user&quot;">​</a></h3><ul><li>类型: <code>number[]</code></li><li>缺省值: <code>[]</code></li></ul><p>BOT 响应的目标用户列表，未配置任何用户时，默认不做使用限制。</p><h3 id="group" tabindex="-1">group <a class="header-anchor" href="#group" aria-label="Permalink to &quot;group&quot;">​</a></h3><ul><li>类型: <code>number[]</code></li><li>缺省值: <code>[]</code></li></ul><p>BOT 响应的目标群组列表，未配置任何群组时，默认不做使用限制。</p><h2 id="banscreenswipe-yml" tabindex="-1">banScreenSwipe.yml <a class="header-anchor" href="#banscreenswipe-yml" aria-label="Permalink to &quot;banScreenSwipe.yml&quot;">​</a></h2><p>群聊刷屏控制相关配置，用于处理群聊中的恶意刷屏行为（BOT 需要为管理员）。</p><h3 id="enable-3" tabindex="-1">enable <a class="header-anchor" href="#enable-3" aria-label="Permalink to &quot;enable&quot;">​</a></h3><ul><li>类型: <a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Boolean" target="_blank" rel="noreferrer">boolean</a></li><li>缺省值: <code>false</code></li></ul><p>是否启用刷屏控制。</p><h3 id="limit" tabindex="-1">limit <a class="header-anchor" href="#limit" aria-label="Permalink to &quot;limit&quot;">​</a></h3><ul><li>类型: <a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Number" target="_blank" rel="noreferrer">number</a></li><li>缺省值: <code>10</code></li></ul><p>连续发送消息几次后触发封禁。</p><h3 id="duration" tabindex="-1">duration <a class="header-anchor" href="#duration" aria-label="Permalink to &quot;duration&quot;">​</a></h3><ul><li>类型: <a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Number" target="_blank" rel="noreferrer">number</a></li><li>缺省值: <code>1800</code></li></ul><p>禁言时长，单位为秒。</p><h3 id="prompt" tabindex="-1">prompt <a class="header-anchor" href="#prompt" aria-label="Permalink to &quot;prompt&quot;">​</a></h3><ul><li>类型: <a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Boolean" target="_blank" rel="noreferrer">boolean</a></li><li>缺省值: <code>true</code></li></ul><p>触发判定后是否给予相关用户提示信息。</p><h3 id="promptmsg" tabindex="-1">promptMsg <a class="header-anchor" href="#promptmsg" aria-label="Permalink to &quot;promptMsg&quot;">​</a></h3><ul><li>类型: <a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/String" target="_blank" rel="noreferrer">string</a></li><li>缺省值: <code>请不要刷屏</code></li></ul><p>触发判定后给予相关用户的提示信息内容，仅 <code>prompt</code> 开启时有效。</p><h2 id="banheavyat-yml" tabindex="-1">banHeavyAt.yml <a class="header-anchor" href="#banheavyat-yml" aria-label="Permalink to &quot;banHeavyAt.yml&quot;">​</a></h2><p>群聊过量 at 处理相关配置，用于处理群聊中的at大量群员的恶意行为（BOT 需要为管理员）。</p><h3 id="enable-4" tabindex="-1">enable <a class="header-anchor" href="#enable-4" aria-label="Permalink to &quot;enable&quot;">​</a></h3><ul><li>类型: <a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Boolean" target="_blank" rel="noreferrer">boolean</a></li><li>缺省值: <code>false</code></li></ul><p>是否启用过量 at 处理控制。</p><h3 id="limit-1" tabindex="-1">limit <a class="header-anchor" href="#limit-1" aria-label="Permalink to &quot;limit&quot;">​</a></h3><ul><li>类型: <a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Number" target="_blank" rel="noreferrer">number</a></li><li>缺省值: <code>10</code></li></ul><p>一条消息中超过多少个 <code>@</code> 消息后触发封禁。</p><h3 id="duration-1" tabindex="-1">duration <a class="header-anchor" href="#duration-1" aria-label="Permalink to &quot;duration&quot;">​</a></h3><ul><li>类型: <a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Number" target="_blank" rel="noreferrer">number</a></li><li>缺省值: <code>1800</code></li></ul><p>禁言时长，单位为秒。</p><h3 id="prompt-1" tabindex="-1">prompt <a class="header-anchor" href="#prompt-1" aria-label="Permalink to &quot;prompt&quot;">​</a></h3><ul><li>类型: <a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Boolean" target="_blank" rel="noreferrer">boolean</a></li><li>缺省值: <code>true</code></li></ul><p>触发判定后是否给予相关用户提示信息。</p><h3 id="promptmsg-1" tabindex="-1">promptMsg <a class="header-anchor" href="#promptmsg-1" aria-label="Permalink to &quot;promptMsg&quot;">​</a></h3><ul><li>类型: <a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/String" target="_blank" rel="noreferrer">string</a></li><li>缺省值: <code>请不要同时at太多人</code></li></ul><p>触发判定后给予相关用户的提示信息内容，仅 <code>prompt</code> 开启时有效。</p>',209),i=[t];function c(d,n,s,h,b,p){return r(),a("div",null,i)}const f=e(o,[["render",c]]);export{m as __pageData,f as default};
